  'ui.help.drag_displays_onto_the_canvas_and_arrange_them_to_match_e881b5': "Drag displays onto the canvas and arrange them to match the PHYSICAL wall",
  'ui.help.panel_hung_sideways_select_it_and_set_how_this_panel_is_e3d3c8': "Panel hung sideways? Select it and set \"How this panel is mounted\" — no need to pre-rotate your video",
  'ui.help.set_bezel_compensation_if_needed_then_fit_player_to_scr_39469c': "Set bezel compensation if needed, then \"Fit player to screens\"",
  'ui.help.assign_a_playlist_to_play_across_all_displays_bb8c4a': "Assign a playlist to play across all displays",
  'ui.help.the_panels_list_below_the_canvas_shows_each_screen_s_on_dd0226': "The Panels list below the canvas shows each screen's online state and links to its device page",
  'ui.help.what_devices_are_supported_c6e59c': "What devices are supported?",
  'ui.help.android_tv_tablets_apk_raspberry_pi_windows_chromeos_lg_db7064': "Android TV/tablets (APK), Raspberry Pi, Windows, ChromeOS, LG webOS, Samsung Tizen, Fire TV, and any device with a web browser.",
  'ui.help.how_does_the_free_trial_work_4a0f2c': "How does the free trial work?",
  'ui.help.new_accounts_on_the_hosted_service_get_a_14_day_trial_o_9b301f': "New accounts on the hosted service get a 14-day trial of the Pro plan with every feature unlocked and no card required. When it ends you move to the Free plan: nothing is deleted, and screens beyond the Free plan's limit pause until you choose a plan. Subscription shows the exact limits for each plan.",
  'ui.help.can_i_use_portrait_mode_displays_b36420': "Can I use portrait mode displays?",
  'ui.help.yes_set_the_orientation_to_portrait_in_the_device_s_inf_4a6ff1': "Yes! Set the orientation to \"Portrait\" in the device's Info tab. The content will be rotated accordingly.",
  'ui.help.what_happens_when_a_device_goes_offline_8f06b8': "What happens when a device goes offline?",
  'ui.help.devices_cache_content_locally_so_they_continue_playing__5c3688': "Devices cache content locally, so they continue playing their playlist even without internet. You'll receive an email alert after 5 minutes of being offline.",
  'ui.help.can_i_self_host_screentinker_af0c7c': "Can I self-host ScreenTinker?",
  'ui.help.how_do_i_update_the_android_app_f839dc': "How do I update the Android app?",
  'ui.help.the_app_checks_for_updates_automatically_every_30_minut_6a3bda': "The app checks for updates automatically every 30 minutes. You can also force an update from the device's Info tab in the dashboard.",
  'ui.help.what_video_formats_are_supported_c0dfbd': "What video formats are supported?",
  'ui.help.mp4_h_264_webm_avi_mkv_mov_for_best_compatibility_use_m_86885a': "MP4 (H.264), WebM, AVI, MKV, MOV. For best compatibility, use MP4 with H.264 encoding.",
  'ui.help.can_i_white_label_the_dashboard_961541': "Can I white-label the dashboard?",
  'ui.help.how_do_i_export_proof_of_play_reports_c1f02f': "How do I export proof-of-play reports?",
  'ui.help.go_to_reports_set_your_date_range_and_filters_then_clic_7a4da1': "Go to Reports, set your date range and filters, then click \"Export CSV\".",
  'ui.help.what_is_a_video_wall_b5c9c3': "What is a video wall?",
  'ui.help.a_video_wall_combines_multiple_displays_into_one_large__619b1b': "A video wall combines multiple displays into one large screen. For example, four TVs in a 2x2 grid showing one big image/video.",
  'ui.help.how_do_i_build_a_wall_from_portrait_sideways_mounted_pa_8ab998': "How do I build a wall from portrait (sideways-mounted) panels?",
  'ui.help.arrange_the_tiles_on_the_wall_canvas_exactly_as_the_pan_07b12f': "Arrange the tiles on the wall canvas exactly as the panels are hung — side by side stays side by side. Then select each tile and set \"How this panel is mounted\" to match how it was turned. The player rotates the content for you, so you do not need a pre-rotated copy of your video. While a display is in a wall, this setting replaces its own Orientation.",
