  'audience.title': 'Audience',
  'audience.subtitle': 'How many people looked at your screens, and for how long. Off unless you turn it on.',
  'audience.privacy_heading': 'How it works, and what it never does',
  'audience.privacy_1': 'The screen\'s own camera and a detector built into the player find faces looking at the screen. All of it happens on the screen.',
  'audience.privacy_2': 'No picture, video, face or anything that could identify a person is stored or ever leaves the screen. Each frame is discarded as soon as it has been counted.',
  'audience.privacy_3': 'Only numbers are sent: per minute, how many people were in view, how many looked, and for how long. Nobody is recognised, followed between minutes, or given an age or gender.',
  'audience.privacy_4': 'The server refuses anything that is not one of those numbers, so a player could not send more even if it tried.',
  'audience.privacy_notice_hint': 'Tell people where you count. docs/audience-counting.md has a ready-to-print notice. Check the rules where your screens are (GDPR, BIPA, CCPA and others) before you switch it on.',
