  // #473 interactive web pages (webpage widget)
  'widget.web.interactive': 'Interactive (walk-up kiosk)',
  'widget.web.interactive_hint': 'Visitors can tap, scroll and fill in forms. The playlist pauses while someone is using the page, and after they leave the page resets and everything they did is wiped. Fullscreen only. Full support on Android, the Windows and Raspberry Pi native players and BrightSign; web, webOS and Tizen screens get a limited version that cannot wipe the site or block other sites.',
  'widget.web.idle_timeout': 'Reset after this many seconds without a touch',
