  'widget.web.idle_warning_off': 'Off (reset straight away)',
  'widget.web.idle_warning_sec': '{n} seconds',
  'widget.web.idle_warning_hint': 'Gives a visitor a moment to tap and carry on. Useful for a shop; on an info page it can be off.',
  'widget.web.wipe_site_data': "Wipe the site's cookies and storage after each visitor",
  'widget.web.wipe_site_data_hint': "Turn off for information pages with nothing to protect (menus, price lists, maps): the cookie banner and the chosen language then stay. Each visitor still gets a fresh page, history and form data. Storage is shared by all web pages on a screen, so another item's wipe on the same screen clears it too. The Windows and Raspberry Pi players keep cookies but not site storage; BrightSign always wipes.",
  'widget.web.keep_consent': "Keep the site's cookie-consent choice between visitors",
  'widget.web.keep_consent_hint': "Only the consent cookies of the allowed sites are kept. Logins, baskets and everything else are still wiped after each visitor. Consent tools that store the choice in localStorage instead of a cookie will still ask.",
  'widget.web.keep_cookie_names': 'Other cookie names to keep',
  'widget.web.keep_cookie_names_ph': 'e.g. shop_consent, cc_*',
  'widget.web.keep_cookie_names_hint': 'Common consent tools (Cookiebot, OneTrust, IAB TCF, CookieYes, Complianz, Borlabs, iubenda, Didomi and others) are recognised already. A trailing * matches a prefix. Never add a login or basket cookie here.',
  'widget.web.zoom_hint': 'Zoom % above also applies to the interactive page: 150 makes a desktop site lay out as if the screen were two-thirds the size.',
